/*********************************************
 * Create table for the tram lines
 * (one row per route variant / direction)
 *
 * Author: Karin Patenge
 * Date: October 2026
 *********************************************/

--
-- Documentation: https://docs.oracle.com/en/database/oracle/oracle-database/26/spatl/
-- Data set: ./insert_tram_lines.sql (© OpenStreetMap contributors, ODbL)
--
-- 26ai features used:
--   * CREATE TABLE IF NOT EXISTS
--   * Identity column with GENERATED BY DEFAULT ON NULL
--   * DEFAULT ON NULL
--   * Annotations on table and columns (usable as metadata by Select AI)
--   * No manual insert into USER_SDO_GEOM_METADATA:
--     the metadata is created automatically with the spatial index.
--     The index needs at least one non-NULL geometry, so it is created
--     at the end of insert_tram_lines.sql
--
-- File encoding: UTF-8 (Croatian diacritics in annotations)
--

-- If needed, drop the table
DROP TABLE IF EXISTS tram_lines PURGE;

-- Create the table
CREATE TABLE IF NOT EXISTS tram_lines (
  route_variant_id      NUMBER
                        GENERATED BY DEFAULT ON NULL AS IDENTITY
                        CONSTRAINT tram_lines_pk PRIMARY KEY
                        ANNOTATIONS (Display 'Route variant ID', Description 'Surrogate key, one row per tram line and direction'),
  line_ref              VARCHAR2(4)
                        NOT NULL
                        ANNOTATIONS (Display 'Tram line', Description 'ZET tram line number, matches TRAM_STATIONS.TRAM_LINE'),
  route_name            VARCHAR2(100)
                        NOT NULL
                        ANNOTATIONS (Display 'Route', Description 'Route variant name, e.g. Tram 6: Črnomerec => Sopot'),
  from_stop             VARCHAR2(100)
                        NOT NULL
                        ANNOTATIONS (Display 'From', Description 'First stop (terminus) of the route variant'),
  to_stop               VARCHAR2(100)
                        NOT NULL
                        ANNOTATIONS (Display 'To', Description 'Last stop (terminus) of the route variant'),
  operator_name         VARCHAR2(50)
                        DEFAULT ON NULL 'ZET'
                        NOT NULL
                        ANNOTATIONS (Display 'Operator', Description 'Public transport operator (Zagrebački električni tramvaj)'),
  geom                  SDO_GEOMETRY
                        NOT NULL
                        ANNOTATIONS (Display 'Track', Description 'Track geometry as line string in driving order, WGS84 lon/lat (SRID 4326)'),
  osm_relation_id       NUMBER(12)
                        ANNOTATIONS (Display 'OSM relation', Description 'OpenStreetMap route relation ID'),
  gtfs_route_id         VARCHAR2(30)
                        ANNOTATIONS (Display 'GTFS route ID', Description 'ZET GTFS route_id, to be filled after loading routes.txt'),
  gtfs_shape_id         VARCHAR2(30)
                        ANNOTATIONS (Display 'GTFS shape ID', Description 'ZET GTFS shape_id, to be filled after loading shapes.txt'),
  data_source           VARCHAR2(200)
                        DEFAULT ON NULL 'OpenStreetMap contributors (ODbL), Overpass API, 2026-10-06'
                        NOT NULL
                        ANNOTATIONS (Display 'Source', Description 'Origin and retrieval date of the geometry'),
  CONSTRAINT tram_lines_uk UNIQUE (line_ref, from_stop, to_stop)
)
ANNOTATIONS (
  Display 'Tram lines',
  Description 'ZET tram lines in Zagreb with track geometry, one row per direction, used in the Spatial Meets AI demo'
);

-- Check the annotations
SELECT
  object_name,
  column_name,
  annotation_name,
  annotation_value
FROM
  USER_ANNOTATIONS_USAGE
WHERE
  object_name = 'TRAM_LINES'
ORDER BY
  column_name NULLS FIRST,
  annotation_name;
